From 66fd93d3d2d315e7e1f22d829e503f3af81dd8be Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:23:36 +0100
Subject: [PATCH] applet, wizard: list trusted but unpaired devices as known
 devices

DualShock 3 controllers are set up over USB, so BlueZ marks them trusted
but never paired and they only showed up in the pairing wizard. Treat
trusted devices like paired ones, so they can be found and forgotten.

BUG: 519548
---
 src/applet/devicesproxymodel.cpp | 8 +++++---
 src/wizard/pages/discover.cpp    | 3 ++-
 2 files changed, 7 insertions(+), 4 deletions(-)

diff --git a/src/applet/devicesproxymodel.cpp b/src/applet/devicesproxymodel.cpp
index bea49e5c..0d0c1b18 100644
--- a/src/applet/devicesproxymodel.cpp
+++ b/src/applet/devicesproxymodel.cpp
@@ -132,10 +132,12 @@ bool DevicesProxyModel::filterAcceptsRow(int source_row, const QModelIndex &sour

     if (m_unpairedOnly) {
         // The Bigscreen KCM has a seperate ListView for unpaired devices, because the wizard isn't used to pair
-        return !index.data(BluezQt::DevicesModel::RemoteNameRole).toString().isEmpty() && !index.data(BluezQt::DevicesModel::PairedRole).toBool(); 
+        return !index.data(BluezQt::DevicesModel::RemoteNameRole).toString().isEmpty() && !index.data(BluezQt::DevicesModel::PairedRole).toBool()
+            && !index.data(BluezQt::DevicesModel::TrustedRole).toBool();
     } else {
-        // Only show paired and connected devices in the KCM and applet
-        return index.data(BluezQt::DevicesModel::PairedRole).toBool() || index.data(BluezQt::DevicesModel::ConnectedRole).toBool();
+        // Only show paired, trusted and connected devices in the KCM and applet
+        return index.data(BluezQt::DevicesModel::PairedRole).toBool() || index.data(BluezQt::DevicesModel::TrustedRole).toBool()
+            || index.data(BluezQt::DevicesModel::ConnectedRole).toBool();
     }
 }

diff --git a/src/wizard/pages/discover.cpp b/src/wizard/pages/discover.cpp
index 8f3786e7..dbf59b74 100644
--- a/src/wizard/pages/discover.cpp
+++ b/src/wizard/pages/discover.cpp
@@ -101,7 +101,8 @@ bool DevicesProxyModel::filterAcceptsRow(int sourceRow, const QModelIndex &sourc
     QModelIndex index = sourceModel()->index(sourceRow, 0, sourceParent);

     bool devicePaired = index.data(BluezQt::DevicesModel::PairedRole).toBool();
-    if (devicePaired) {
+    bool deviceTrusted = index.data(BluezQt::DevicesModel::TrustedRole).toBool();
+    if (devicePaired || deviceTrusted) {
         return false;
     }

-- 
